solutionCode:
use std::collections::HashMap;

pub fn contar(palavras: Vec<String>) -> HashMap<String, i32> {
    let mut contagem = HashMap::new();
    for palavra in palavras {
        *contagem.entry(palavra).or_insert(0) += 1;
    }
    contagem
}

testsCode:
use desafio::contar;

#[test]
fn testa_o_sol_e_a_lua() {
    let c = contar(vec![String::from("sol"), String::from("lua"), String::from("sol")]);
    assert_eq!(c["sol"], 2);
    assert_eq!(c["lua"], 1);
}

#[test]
fn testa_a_quantidade_de_chaves() {
    let c = contar(vec![String::from("sol"), String::from("sol")]);
    assert_eq!(c.len(), 1);
}
